// Public scenario library. Private Scenario Editor exports can replace this file.
window.ASCENDIA_CUSTOM_SCENARIOS = [
{id:'angry-boss',title:'The Angry Boss',emoji:'😤',category:'work',intro:'Your manager calls you into a room. A deadline slipped, and they are clearly frustrated.',start:'start',nodes:{
start:{text:'Your manager closes the laptop and says, “This was supposed to be done yesterday. What happened?” Your stomach drops.',choices:[["Own the delay and explain the concrete reason.","own"],["Apologise repeatedly and promise it will never happen again.","apologise"],["Point out that another teammate was late too.","blame"]]},
own:{text:'You say, “I missed the deadline. The data arrived late, but I also should have flagged the risk earlier.” They pause.',choices:[["Ask what outcome they need now.","plan"],["Ask whether they are disappointed in you.","emotion"],["Stay quiet and wait for them to respond.","quiet"]]},
apologise:{text:'You apologise several times. Your manager says, “I need a solution, not just an apology.”',choices:[["Ask what would make the recovery useful.","plan"],["Offer to work late without checking what is realistic.","overpromise"],["Say you understand and ask for five minutes to make a plan.","pause"]]},
blame:{text:'You mention your teammate. Your manager says, “We can discuss their work separately. I’m asking about yours.”',choices:[["Bring the conversation back to your responsibility.","own"],["Argue that the standard is unfair.","argue"],["Say nothing and accept the criticism.","quiet"]]},
plan:{text:'You ask what outcome matters most. Your manager gives you two priorities and a new deadline.',choices:[["Repeat the plan back to confirm it.","confirm"],["Ask for help with the highest-risk part.","help"],["Say you will figure it out alone.","solo"]]},
emotion:{text:'They look surprised. “I’m frustrated with the missed deadline. I’m not asking you to read my mind.”',choices:[["Thank them for clarifying and return to the work.","confirm"],["Ask whether you are still trusted.","trust"]]},
quiet:{text:'The silence stretches. You realise staying silent is not the same as staying calm.',choices:[["Say, “I hear the feedback. Can we agree on next steps?”","plan"],["Ask for a moment to collect yourself.","pause"]]},
overpromise:{end:'You promise a heroic turnaround without checking your capacity. TAKEAWAY: confidence includes making commitments you can actually keep. 🌱'},
pause:{end:'You take a breath, then build a realistic recovery plan. TAKEAWAY: pausing is not weakness; it can keep pressure from choosing your words for you. ✨'},
confirm:{end:'You leave with a clear plan instead of a cloud of shame. TAKEAWAY: accountability and self-respect can exist in the same conversation. 💛'},
help:{end:'You ask for targeted help on the risky part. TAKEAWAY: asking for support early can be a professional strength, not a confession of failure. 🤝'},
solo:{end:'You insist on doing everything alone. TAKEAWAY: independence is useful; refusing reasonable support can make problems harder than they need to be. 🌙'},
trust:{end:'You ask directly about trust and get a nuanced answer. TAKEAWAY: difficult feedback is information about a moment, not a complete definition of you. 🌱'},
argue:{end:'The conversation becomes a debate about fairness instead of a plan. TAKEAWAY: you can raise a fairness concern while still answering the question in front of you. 🌼'}
}},
{id:'speak-up-meeting',title:'The Meeting Where You Have an Idea',emoji:'💡',category:'speaking',intro:'You have a genuinely useful idea, but three confident people are already talking over one another.',start:'start',nodes:{
start:{text:'The discussion moves toward a decision. You know one detail that could save the team time, but your heart starts racing.',choices:[["Raise your hand and wait.","hand"],["Jump in with “Can I add one thing?”","jump"],["Decide it is probably obvious anyway.","silence"]]},
hand:{text:'The room notices your raised hand. Someone says, “Go ahead.”',choices:[["Give the idea in one sentence first.","clear"],["Explain the entire backstory.","long"],["Say “Never mind” because everyone is looking.","retreat"]]},
jump:{text:'You get an opening. Your voice comes out softer than you intended.',choices:[["Repeat the key sentence more clearly.","clear"],["Make a joke about being nervous.","joke"],["Rush through everything.","rush"]]},
silence:{text:'The meeting continues. Then someone proposes almost exactly what you were thinking.',choices:[["Add your missing detail now.","clear"],["Stay quiet because the moment passed.","retreat"],["Message the organiser afterward.","follow"]]},
clear:{text:'You say the idea simply, then stop. There is a beat of silence — and someone asks a useful follow-up.',choices:[["Answer the question directly.","answer"],["Say you need a second to think.","pause"],["Keep adding details before they ask.","overexplain"]]},
long:{text:'You explain every step. Halfway through, you realise the room has lost the thread.',choices:[["Summarise the point in one sentence.","answer"],["Keep explaining until it makes sense.","overexplain"]]},
joke:{text:'Everyone laughs kindly, but you notice the joke became a shield.',choices:[["Return to the idea without apologising.","clear"],["Let the joke become the whole contribution.","retreat"]]},
rush:{text:'You finish in a breath. A colleague says, “Sorry, can you repeat the last part?”',choices:[["Repeat it slowly.","answer"],["Assume they were not listening.","retreat"]]},
answer:{end:'You answer the question, and the idea gets considered on its merits. TAKEAWAY: being heard does not require sounding fearless. It requires giving people something clear to hear. 🎙️'},
pause:{end:'You pause, think, then answer. TAKEAWAY: a two-second pause can look much more composed from the outside than it feels on the inside. 💙'},
overexplain:{end:'You keep adding information until your original point disappears. TAKEAWAY: clarity often gets stronger when you stop after the useful sentence. ✨'},
retreat:{end:'You let the moment pass. TAKEAWAY: retreating is allowed, but noticing the pattern gives you something to practise next time. 🌱'},
follow:{end:'You send the detail afterward and it helps the team. TAKEAWAY: confidence has more than one doorway; speaking live is one skill, following up is another.'}
}},
{id:'friend-boundary',title:'The Friend Who Keeps Cancelling',emoji:'📱',category:'boundaries',intro:'You have rearranged your week twice. Your friend cancels again an hour before you meet.',start:'start',nodes:{
start:{text:'Your friend texts, “I’m so sorry 😭 Can we do next week?” You feel disappointed and irritated.',choices:[["Say honestly that the pattern is bothering you.","honest"],["Say “No worries!” even though you are upset.","hide"],["Leave them on read.","silent"]]},
honest:{text:'You say, “I get that things happen, but repeated cancellations are making me stop planning around this.”',choices:[["Suggest a plan that requires less rearranging.","solution"],["Ask them to tell you when they actually have capacity.","capacity"],["Tell them you are done with the friendship.","explode"]]},
hide:{text:'You type “No worries!” and put your phone down. Ten minutes later you are still annoyed.',choices:[["Send a second message correcting yourself kindly.","repair"],["Keep quiet and hope they notice.","silent"],["Make a passive-aggressive joke.","joke"]]},
silent:{text:'They send another message asking if you are angry. You have an opening to be honest.',choices:[["Explain what actually upset you.","honest"],["Say you are fine.","hide"]]},
solution:{end:'You agree on a lower-pressure plan that protects your time. TAKEAWAY: a boundary can change the shape of a relationship without ending it. 🚪'},
capacity:{end:'You stop chasing a calendar that keeps moving. TAKEAWAY: letting someone show you their capacity can be kinder than repeatedly trying to extract availability from them. 🌱'},
explode:{end:'You send a message you cannot take back. TAKEAWAY: a real boundary can be firm without becoming a punishment. 🌼'},
repair:{end:'You correct yourself while the moment is still small. TAKEAWAY: you are allowed to revise a people-pleasing answer. 💛'},
joke:{end:'The joke communicates irritation without clarity. TAKEAWAY: if you need a boundary, direct language usually creates less confusion than hints. ✨'}
}},
{id:'networking-room',title:'The Networking Room',emoji:'🪩',category:'social',intro:'You walk into a room where almost everyone seems to know someone already.',start:'start',nodes:{
start:{text:'You stand near the entrance with your drink. A small group is laughing nearby. Nobody looks particularly unapproachable, but your brain says “DO NOT EMBARRASS YOURSELF.”',choices:[["Introduce yourself to one person.","intro"],["Look for another person standing alone.","alone"],["Stay on your phone for ten minutes.","phone"]]},
intro:{text:'You say, “Hi, I’m ___ — how do you know everyone here?” They smile and answer.',choices:[["Ask a follow-up question.","follow"],["Share one thing about yourself.","share"],["Leave after the first answer.","exit"]]},
alone:{text:'You spot someone alone near the window. You are both holding your phones.',choices:[["Say, “Hey, I don't think we've met.”","hello"],["Ask what brought them here.","hello"],["Decide approaching would be weird.","phone"]]},
phone:{text:'Ten minutes pass. You have learned nothing about the room except who posted a story.',choices:[["Put the phone away for five minutes.","hello"],["Text someone you know for rescue.","rescue"],["Leave.","exit"]]},
follow:{text:'They tell you about a club they are involved in and ask what you do.',choices:[["Answer honestly and ask another question.","connect"],["Give a polished answer you think sounds impressive.","perform"]]},
share:{text:'You mention something you actually enjoy. Their eyes light up because they like it too.',choices:[["Ask what they like about it.","connect"],["Change the subject quickly.","exit"]]},
hello:{text:'They introduce themselves. The conversation has begun, even though you still feel nervous.',choices:[["Ask one easy question.","connect"],["Say you are nervous at events like this.","honest"]]},
connect:{end:'The conversation lasts several minutes and ends naturally. TAKEAWAY: a successful social interaction can be tiny — one introduction, one question, one genuine exchange. 🪩'},
perform:{end:'You spend the conversation managing your image. TAKEAWAY: confidence often becomes easier when you trade “How do I look?” for “What am I curious about?” 🌱'},
honest:{end:'They admit they feel awkward too. TAKEAWAY: naming a normal human feeling can create connection instead of ruining it. 🤝'},
rescue:{end:'You leave the situation earlier than planned. TAKEAWAY: knowing when to leave is also self-trust. Next time, you can stay for five more minutes if you want. 🌙'},
exit:{end:'You end the interaction or leave politely. TAKEAWAY: confidence is not forcing yourself to stay; it is knowing you can choose your next move. ✨'}
}},
{id:'wrong-order',title:'The Restaurant Mix-Up',emoji:'🍜',category:'assertiveness',intro:'Your meal arrives completely wrong. The server is busy and you do not want to be “difficult.”',start:'start',nodes:{
start:{text:'You ordered a vegetarian bowl. A meat dish is placed in front of you. The server is already turning away.',choices:[["Call them back politely.","ask"],["Eat around it and say nothing.","avoid"],["Wait until they notice.","wait"]]},
ask:{text:'You say, “Sorry, I ordered the vegetarian bowl. Could you help me change this?”',choices:[["Thank them and wait.","waitfix"],["Apologise for bothering them.","apologise"],["Ask how long it will take.","time"]]},
wait:{text:'You wait. The server returns and asks if everything is okay.',choices:[["Tell them the order is wrong.","ask"],["Say it is fine.","avoid"]]},
avoid:{text:'You try to make the situation work, but you know you cannot eat the dish as ordered.',choices:[["Ask for help before eating it.","ask"],["Decide it is too late.","leave"]]},
apologise:{text:'The server says, “No problem.” Nothing dramatic happens.',choices:[["Let the apology end there.","waitfix"],["Keep explaining why you feel bad.","spiral"]]},
time:{text:'They say it will take about ten minutes.',choices:[["Say that is okay and wait.","waitfix"],["Ask whether another option is quicker.","alternative"]]},
waitfix:{end:'Your corrected meal arrives. TAKEAWAY: making a reasonable request is not the same as creating a problem. 🍜'},
spiral:{end:'You turn a simple request into a referendum on whether you are annoying. TAKEAWAY: you can be considerate without treating your needs as an inconvenience. 🌼'},
alternative:{end:'You ask for options instead of demanding one outcome. TAKEAWAY: assertiveness can sound collaborative, not aggressive. ✨'},
leave:{end:'You decide not to eat and leave frustrated. TAKEAWAY: avoidance can protect you in the moment, but practising clear requests makes future moments easier. 🌱'}
}},
{id:'pitch-rejection',title:'The Pitch That Gets Rejected',emoji:'📩',category:'rejection',intro:'You finally send an idea to a brand or organisation. The reply arrives: “Thanks, but not at this time.”',start:'start',nodes:{
start:{text:'You stare at the email. You spent hours on the pitch. Your first thought is, “Of course they said no.”',choices:[["Separate the fact from the story.","facts"],["Immediately send another pitch.","rush"],["Decide you should stop pitching.","quit"]]},
facts:{text:'The fact: one pitch was declined. The story: nobody will ever want what you make.',choices:[["Ask whether a polite follow-up is appropriate.","follow"],["Review what you can actually learn.","learn"],["Take the rejection personally for the rest of the day.","spiral"]]},
rush:{text:'You open another email draft before processing the first.',choices:[["Pause and take ten minutes.","facts"],["Send five pitches to prove a point.","spam"]]},
quit:{text:'You close your laptop and decide this means you are not cut out for it.',choices:[["Write down what happened without interpretation.","facts"],["Ask someone you trust for feedback on the pitch.","learn"]]},
follow:{end:'You send one respectful follow-up and accept whatever comes next. TAKEAWAY: persistence has a boundary; it does not require chasing. 🌱'},
learn:{end:'You identify one thing to improve and one thing that was already solid. TAKEAWAY: feedback is more useful when it is specific enough to act on. ✨'},
spiral:{end:'You let one email become a verdict on yourself. TAKEAWAY: disappointment is real, but a single response contains limited information. 💛'},
spam:{end:'You flood your inbox with pitches. TAKEAWAY: confidence is not frantic activity; sometimes the brave move is slowing down enough to learn.'}
}},
{id:'class-question',title:'The Question You Think Is “Stupid”',emoji:'🙋🏽‍♀️',category:'speaking',intro:'The lecturer moves on quickly. You are still confused about one step and everyone else looks quiet.',start:'start',nodes:{
start:{text:'Your brain says, “Everyone understands this. If you ask, they will know you are behind.”',choices:[["Raise your hand.","ask"],["Write the question down for later.","later"],["Pretend you understand.","pretend"]]},
ask:{text:'The lecturer calls on you. Your voice shakes slightly.',choices:[["Ask the exact point you are confused about.","clear"],["Start apologising before asking.","apology"],["Say never mind.","retreat"]]},
later:{text:'After class, you still have the same question. You see a classmate packing up.',choices:[["Ask the classmate.","peer"],["Look it up later and move on.","study"]]},
pretend:{text:'You copy the next slide, but the next concept depends on the part you missed.',choices:[["Ask now even though it feels late.","ask"],["Stay quiet and hope it makes sense later.","study"]]},
clear:{end:'The lecturer answers, and another student nods because they were wondering too. TAKEAWAY: a clear question can help more than one person in the room. 📚'},
apology:{end:'You eventually ask, but the apology takes longer than the question. TAKEAWAY: curiosity does not require an apology. You are allowed to learn. 🌱'},
retreat:{end:'You let the question go. TAKEAWAY: one missed opportunity is not a failure — it is a useful signal for what to practise next time.'},
peer:{end:'Your classmate explains it in a different way and you finally get it. TAKEAWAY: asking for clarification is a learning skill, not a status loss. 💙'},
study:{end:'You study the concept later. TAKEAWAY: there are many ways to solve a knowledge gap; the important part is noticing and addressing it. ✨'}
}},
{id:'group-project',title:'The Group Project Takeover',emoji:'🧩',category:'boundaries',intro:'One teammate keeps taking over every decision. You have stopped sharing ideas because it feels pointless.',start:'start',nodes:{
start:{text:'They say, “I already made the whole outline. Just follow it.” You actually have a better structure for one section.',choices:[["Suggest comparing the two structures.","compare"],["Let them decide everything.","yield"],["Tell them their idea is bad.","attack"]]},
compare:{text:'You say, “I have a different structure for this part. Can we compare them against the assignment criteria?”',choices:[["Use the criteria to decide.","criteria"],["Defend your idea personally.","ego"],["Offer a small hybrid.","hybrid"]]},
yield:{text:'You agree. Later, the project hits a problem you had anticipated.',choices:[["Bring up the concern now.","repair"],["Stay quiet because you already agreed.","silent"]]},
attack:{text:'The room gets tense. Your teammate asks what exactly is wrong with their idea.',choices:[["Explain the concrete issue.","criteria"],["Double down.","ego"]]},
criteria:{end:'The group chooses based on the actual task rather than personalities. TAKEAWAY: assertiveness becomes easier when you anchor a disagreement to shared criteria. 🧩'},
hybrid:{end:'You combine useful pieces from both ideas. TAKEAWAY: confidence is not always winning the argument; sometimes it is contributing without needing ownership of the whole answer. ✨'},
yield:{end:'You keep the peace but lose your voice. TAKEAWAY: avoiding every disagreement can cost you participation over time. 🌱'},
ego:{end:'The disagreement becomes personal. TAKEAWAY: a strong point does not need a strong attack attached to it. 🌼'},
repair:{end:'You raise the concern respectfully and the team adjusts. TAKEAWAY: changing course is easier when someone is willing to say what they see. 💙'},
silent:{end:'You stay quiet and watch the problem grow. TAKEAWAY: speaking earlier often requires less force than speaking after frustration has piled up.'}
}},
{id:'phone-call',title:'The Call You Keep Avoiding',emoji:'📞',category:'assertiveness',intro:'You need to make a simple phone call. You have postponed it for three days because you are imagining every possible awkward moment.',start:'start',nodes:{
start:{text:'The number is on your screen. The task itself is simple, but your brain has turned it into a performance.',choices:[["Write three bullet points and call.","call"],["Rehearse the whole conversation first.","rehearse"],["Send another message instead.","text"]]},
call:{text:'They answer. “Hello?” There is a tiny silence.',choices:[["Say your name and why you are calling.","clear"],["Start with “Sorry to bother you.”","sorry"],["Hang up and try later.","hang"]]},
rehearse:{text:'You have written a full script. When they answer, they ask a question you did not predict.',choices:[["Answer naturally.","clear"],["Say you will call back.","hang"]]},
text:{text:'You send a message instead. It works, but the original task was easier by phone.',choices:[["Decide to make one short call anyway.","call"],["Leave it there.","avoid"]]},
clear:{end:'The call lasts three minutes. TAKEAWAY: the imagined awkwardness was much bigger than the actual task. 📞'},
sorry:{end:'You make the request, but frame your existence as an interruption. TAKEAWAY: politeness does not require apologising for every reasonable request. 🌱'},
hang:{end:'You postpone again. TAKEAWAY: avoidance can feel protective while quietly teaching your brain that the task is dangerous. One tiny call next time. 💛'},
avoid:{end:'You choose the easier route today. TAKEAWAY: flexibility is useful, but if you always avoid the feared version, the fear gets very little evidence against it.'}
}},
{id:'compliment',title:'The Compliment You Actually Mean',emoji:'🌷',category:'social',intro:'Someone you barely know does something impressive. You want to compliment them, but worry it will sound weird.',start:'start',nodes:{
start:{text:'They finish presenting. You genuinely liked how clearly they explained the difficult part.',choices:[["Tell them specifically what you liked.","specific"],["Give a vague “good job” and leave.","vague"],["Say nothing because you do not know them well.","silent"]]},
specific:{text:'You say, “I liked how you explained that last part — it made the idea much easier to follow.”',choices:[["Let the compliment stand.","receive"],["Add five more reasons so they know you mean it.","overdo"]]},
vague:{text:'They smile and say thank you. You wonder if it sounded automatic.',choices:[["Add one genuine detail.","specific"],["Leave it there.","receive"]]},
silent:{end:'You keep the compliment to yourself. TAKEAWAY: not every thought needs to be shared, but practising kind expression can make social courage feel more natural. 🌷'},
receive:{end:'They thank you. You do not need to manage what they think of you afterward. TAKEAWAY: confidence can include giving something kind without demanding a particular response. 💛'},
overdo:{end:'The compliment becomes a speech. TAKEAWAY: sincerity does not need volume; one specific sentence can be enough.'}
}},
{id:'unfair-comment',title:'The Comment That Crossed a Line',emoji:'🚧',category:'boundaries',intro:'Someone makes a joke about you in front of others. Everyone laughs, but it does not feel funny to you.',start:'start',nodes:{
start:{text:'The person grins and says, “Relax, it’s just a joke.” You feel embarrassed and angry.',choices:[["Say calmly that you did not like it.","direct"],["Laugh along even though you are hurt.","laugh"],["Make an even harsher joke back.","retaliate"]]},
direct:{text:'You say, “I know you meant it as a joke, but I did not like being the target. Please leave that out next time.”',choices:[["Stop talking and let them respond.","hold"],["Explain your entire history with this topic.","explain"]]},
laugh:{text:'Everyone moves on. You feel smaller afterward.',choices:[["Bring it up privately later.","private"],["Decide it is not worth mentioning.","drop"]]},
retaliate:{text:'The room goes quiet. Now both of you feel exposed.',choices:[["Own your part and reset the conversation.","repair"],["Keep escalating.","escalate"]]},
hold:{end:'They apologise and adjust, or you learn something important from their response. TAKEAWAY: a boundary is information about how you want to be treated, not a demand to control someone’s reaction. 🚧'},
explain:{end:'You give a long explanation and still feel uncertain. TAKEAWAY: you can give context, but you do not need to prove that your boundary is legitimate. 🌱'},
private:{end:'You speak privately and explain the impact without creating a public fight. TAKEAWAY: choosing the right setting is part of assertiveness. 💙'},
drop:{end:'You let it go. TAKEAWAY: not every uncomfortable moment needs a confrontation, but noticing what you tolerate helps you choose your boundaries intentionally.'},
repair:{end:'You acknowledge your retaliation and state what you actually wanted. TAKEAWAY: confidence includes repairing your own mistakes while still naming the original issue. ✨'},
escalate:{end:'The exchange becomes a competition. TAKEAWAY: matching disrespect with disrespect may feel powerful briefly while making the original problem harder to solve.'},
}},
{id:'new-club',title:'The First Day in a New Club',emoji:'🎨',category:'social',intro:'You joined a club because you wanted to meet people. At the first meeting, nobody seems to know you.',start:'start',nodes:{
start:{text:'You arrive early. Two members are already chatting. You can feel yourself considering an exit before the meeting even starts.',choices:[["Introduce yourself to them.","intro"],["Sit quietly and wait for the organiser.","wait"],["Leave and tell yourself you will come next week.","leave"]]},
intro:{text:'You say hello. They welcome you and ask what brought you there.',choices:[["Answer honestly.","honest"],["Ask them about the club first.","question"],["Give a short answer and find a seat.","seat"]]},
wait:{text:'The organiser arrives and greets everyone. They ask your name.',choices:[["Introduce yourself and mention you are new.","honest"],["Give only your name.","seat"]]},
leave:{end:'You leave before anyone gets a chance to know you. TAKEAWAY: you can try again next time, and the fact that you left today does not erase your courage in joining at all. 🌱'},
honest:{end:'You say you joined because you wanted to try something new. Someone says they were nervous at their first meeting too. TAKEAWAY: being new is a shared experience, not a personal flaw. 🎨'},
question:{end:'You ask about the club and learn something interesting. TAKEAWAY: curiosity can carry a conversation when you do not know what to say about yourself. ✨'},
seat:{end:'You take a seat and stay through the meeting. TAKEAWAY: participation can begin with simply allowing yourself to belong in the room before you feel like you belong.'}
}},
{id:'asking-for-help',title:'The “I Can Do It Myself” Moment',emoji:'🛠️',category:'work',intro:'You are stuck on something you have been trying to solve alone for an hour.',start:'start',nodes:{
start:{text:'You could ask someone nearby. But a voice in your head says, “If you were actually good at this, you would know.”',choices:[["Ask a specific question.","ask"],["Keep struggling alone.","alone"],["Pretend you are not stuck.","hide"]]},
ask:{text:'You say, “Could I check one thing with you? I have tried A and B, and I cannot see what I am missing.”',choices:[["Listen to their explanation.","listen"],["Defend why your approach should have worked.","defend"]]},
alone:{text:'Another thirty minutes pass. Your frustration is now affecting your work.',choices:[["Ask now and show what you already tried.","ask"],["Take a break and return later.","break"]]},
hide:{text:'Someone asks how it is going. You say, “Fine.”',choices:[["Correct yourself and say you are stuck.","ask"],["Keep hiding it.","spiral"]]},
listen:{end:'They show you one missing step and you continue. TAKEAWAY: asking for help after trying is often evidence of initiative, not incompetence. 🛠️'},
defend:{end:'You spend more time proving your first idea than learning the missing step. TAKEAWAY: being teachable and being capable are not opposites.'},
break:{end:'You take a short break and return with a clearer head. TAKEAWAY: self-reliance can include knowing when to pause instead of grinding harder. 🌿'},
spiral:{end:'The problem grows while everyone thinks you are fine. TAKEAWAY: hiding difficulty can cost more energy than asking for a small amount of help.'}
}},
{id:'interview',title:'The Interview Question You Did Not Prepare For',emoji:'🪞',category:'speaking',intro:'An interviewer asks a question you did not rehearse. Your prepared answer disappears from your brain.',start:'start',nodes:{
start:{text:'They ask, “Tell me about a time you changed your mind.” You have no perfect story ready.',choices:[["Take two seconds and think.","pause"],["Start talking immediately.","ramble"],["Say you cannot think of one.","blank"]]},
pause:{text:'You breathe. You remember a small disagreement from a group project.',choices:[["Tell the story using what happened, what changed, and what you learned.","story"],["Try to make the story sound more impressive than it was.","inflate"]]},
ramble:{text:'You mention three unrelated examples and lose your original point.',choices:[["Stop and summarise one example.","story"],["Keep talking to fill the silence.","fill"]]},
blank:{text:'The interviewer gives you a moment. You can still recover.',choices:[["Say, “Let me think of a useful example.”","pause"],["Give up on the question.","quit"]]},
story:{end:'You give a simple, honest example. TAKEAWAY: strong speaking is not memorising perfect sentences; it is organising your thoughts under pressure. 🎙️'},
inflate:{end:'You make the story sound impressive and lose some authenticity. TAKEAWAY: a small truthful example can be more useful than a dramatic invented one.'},
fill:{end:'You keep talking until the answer ends. TAKEAWAY: silence is not an emergency. A pause can help you choose the next sentence.'},
quit:{end:'You leave the question behind. TAKEAWAY: one difficult question is a practice opportunity, not a total verdict on your communication.'}
}},
{id:'late-text',title:'The Message You Need to Send',emoji:'💬',category:'rejection',intro:'You need to tell someone you cannot make it. You have rewritten the message six times.',start:'start',nodes:{
start:{text:'Your draft says: “Heyyy I’m so so sorry, I feel really bad, maybe if it is okay and you are not upset…”',choices:[["Delete the apology spiral and state the fact.","clear"],["Send the over-explained version.","long"],["Do not send anything.","avoid"]]},
clear:{text:'You write: “I can’t make it tonight. I’m sorry for the late notice. Can we reschedule for Thursday?”',choices:[["Send it.","send"],["Add three more paragraphs.","long"]]},
long:{end:'You send a long explanation and then wait anxiously for a reply. TAKEAWAY: more words do not always create more certainty. Clear and kind is enough.'},
avoid:{end:'The person waits without information. TAKEAWAY: fear of disappointing someone can sometimes create a bigger inconvenience than the honest message would have.'},
send:{end:'You send the message and put your phone down. TAKEAWAY: confidence can be the ability to tolerate not knowing exactly how someone will respond. 💬'}
}}
,{"id":"angry-boss","title":"The Angry Boss","emoji":"😤","category":"work","intro":"Your manager is frustrated about a mistake and calls you into a private conversation.","start":"start","nodes":{"start":{"text":"Your manager closes the laptop and says, “I’m really disappointed. This should not have happened.” Your stomach drops.","choices":[["Defend yourself immediately.","defend"],["Ask what specifically went wrong.","clarify"],["Take a breath and listen first.","listen"]]},"defend":{"text":"You explain three reasons the mistake happened. Your manager is still visibly frustrated.","choices":[["Keep explaining.","overexplain"],["Ask what outcome they need now.","clarify"]]},"listen":{"text":"You let the silence sit. Your manager explains the impact and what the team needs next.","choices":[["Ask one clarifying question.","clarify"],["Promise you will never make a mistake again.","promise"]]},"clarify":{"text":"You ask, “What would you like me to do differently next time?” The tone softens slightly.","choices":[["Offer a concrete recovery plan.","plan"],["Ask for feedback on your process.","feedback"]]},"overexplain":{"end":"The conversation turns into a defence of the past. TAKEAWAY: context can matter, but clarity about the next step often helps more than proving you had reasons."},"promise":{"end":"You promise perfection, which nobody can realistically deliver. TAKEAWAY: accountability is stronger when it includes a practical plan, not impossible promises."},"plan":{"end":"You agree on two concrete next steps and a check-in. TAKEAWAY: you can accept responsibility without turning one mistake into a verdict on your entire ability."},"feedback":{"end":"You leave with specific feedback instead of guessing what went wrong. TAKEAWAY: confident people can ask for information when the situation is uncomfortable."}}},{"id":"class-question","title":"The “Stupid” Question","emoji":"🙋🏽","category":"speaking","intro":"You are in class and have a question, but you worry everyone else already understands.","start":"start","nodes":{"start":{"text":"The lecturer moves to the next slide. You are almost certain you missed one important connection.","choices":[["Raise your hand.","ask"],["Wait and search later.","wait"],["Ask a friend after class.","friend"]]},"ask":{"text":"The room gets quiet when the lecturer calls on you.","choices":[["Ask the question simply.","clear"],["Start with “Sorry if this is obvious…”","apology"]]},"wait":{"text":"You write the question down, but the next topic becomes even harder to follow.","choices":[["Ask before the lecture moves on.","ask"],["Keep waiting.","avoid"]]},"friend":{"text":"Your friend says they were wondering the same thing.","choices":[["Ask the lecturer together after class.","clear"],["Decide not to bother them.","avoid"]]},"clear":{"end":"The lecturer answers, and two other students nod. TAKEAWAY: the question you fear is embarrassing may be exactly what someone else needed explained too."},"apology":{"end":"The question gets answered, but you spend more time apologising than necessary. TAKEAWAY: curiosity does not need a disclaimer."},"avoid":{"end":"You leave without clarity. TAKEAWAY: avoiding one uncomfortable moment can create a longer learning problem."}}},{"id":"roommate-conflict","title":"The Angry Roommate","emoji":"🏠","category":"boundaries","intro":"Your roommate is angry about something you did and starts the conversation at full volume.","start":"start","nodes":{"start":{"text":"“You always do this!” they say. You feel blamed and immediately want to fight back.","choices":[["Match their energy.","fight"],["Ask them to tell you the specific issue.","specific"],["Leave without saying anything.","leave"]]},"fight":{"text":"Both voices get louder. You are now arguing about five different old incidents.","choices":[["Bring it back to today.","reset"],["Keep listing their mistakes.","score"]]},"specific":{"text":"They explain the actual issue: dishes were left overnight and guests arrived unexpectedly.","choices":[["Acknowledge your part and discuss a solution.","solve"],["Say they should have asked more politely.","tone"]]},"leave":{"text":"You leave the room. The issue is still waiting when you return.","choices":[["Come back when calm.","reset"],["Avoid the roommate for days.","avoid"]]},"reset":{"end":"You bring the conversation back to one problem instead of every past problem. TAKEAWAY: calm does not mean passive; it can help you stay on the issue that can actually be solved."},"score":{"end":"The argument becomes a competition over who has behaved worse. TAKEAWAY: proving someone else is imperfect rarely solves the thing you actually need changed."},"solve":{"end":"You both agree on a practical house rule. TAKEAWAY: accountability and boundaries can exist together."},"tone":{"end":"You raise the tone issue without abandoning the original problem. TAKEAWAY: how something is said matters, but it does not always erase the content that needs addressing."},"avoid":{"end":"The tension grows through silence. TAKEAWAY: taking space can help, but disappearing indefinitely usually does not create a solution."}}},{"id":"rejection-email","title":"The Rejection Email","emoji":"📩","category":"rejection","intro":"You open an email you have been waiting for. The answer is no.","start":"start","nodes":{"start":{"text":"“Thank you for your application…” You already know what comes next.","choices":[["Close the email immediately.","close"],["Read the full message.","read"],["Tell yourself you knew you would fail.","spiral"]]},"close":{"text":"You close it, but keep checking your inbox.","choices":[["Return later and read it calmly.","read"],["Decide you will never apply again.","quit"]]},"read":{"text":"The message is polite. It gives no detailed reason, but invites future applications.","choices":[["Save the opportunity and move on.","move"],["Ask if feedback is available.","feedback"]]},"spiral":{"end":"You turn one outcome into a story about your entire future. TAKEAWAY: a rejection is an event; the meaning you attach to it is a separate thing."},"quit":{"end":"You protect yourself from another no by removing yourself from future opportunities. TAKEAWAY: avoiding rejection can also avoid possibility."},"move":{"end":"You let yourself be disappointed, then return to your next plan. TAKEAWAY: resilience can look very ordinary: feel it, then keep moving."},"feedback":{"end":"You ask politely for feedback and accept that they may not be able to provide it. TAKEAWAY: asking for useful information is different from asking someone to reverse their decision."}}},{"id":"group-project","title":"The Group Project Takeover","emoji":"🧩","category":"assertiveness","intro":"One group member keeps making decisions without asking the rest of the team.","start":"start","nodes":{"start":{"text":"You open the shared document and see that half your section has been rewritten without discussion.","choices":[["Say nothing.","silent"],["Message them directly and calmly.","direct"],["Complain about them to another teammate.","gossip"]]},"silent":{"text":"They continue assigning tasks without checking availability.","choices":[["Speak up at the next meeting.","meeting"],["Quietly redo your section.","redo"]]},"direct":{"text":"You write: “I noticed some changes were made to my section. Can we agree on edits before changing each other’s work?”","choices":[["Suggest a shared process.","process"],["Make the message harsher so they take you seriously.","harsh"]]},"gossip":{"end":"The frustration spreads, but the actual group process does not improve. TAKEAWAY: talking about a problem and addressing it are different actions."},"redo":{"end":"You finish the work but feel increasingly resentful. TAKEAWAY: avoiding conflict can sometimes move the workload into a different kind of stress."},"meeting":{"end":"You raise the issue and the group agrees on a simple editing rule. TAKEAWAY: you can challenge a process without attacking a person."},"process":{"end":"The group creates a shared editing process. TAKEAWAY: assertiveness can be practical and collaborative."},"harsh":{"end":"Your point gets buried under the tone. TAKEAWAY: firmness does not require hostility."}}},{"id":"networking-name","title":"I Forgot Their Name","emoji":"🪩","category":"social","intro":"You meet someone interesting and immediately forget their name.","start":"start","nodes":{"start":{"text":"They smile and say, “Great to meet you!” Your brain has already deleted the name.","choices":[["Ask them to repeat it.","ask"],["Pretend you remember.","pretend"],["Avoid saying their name.","avoid"]]},"ask":{"text":"You smile and say, “I’m sorry, remind me of your name?”","choices":[["Repeat it back.","repeat"],["Make a joke about your memory.","joke"]]},"pretend":{"text":"The conversation continues, but you are mentally panicking about being caught.","choices":[["Ask naturally later.","ask"],["Keep pretending.","continue"]]},"avoid":{"end":"You have a pleasant conversation but avoid using their name completely. TAKEAWAY: not every imperfect social moment needs to be fixed, but directness is often less awkward than imagined."},"repeat":{"end":"You repeat the name once and the conversation continues normally. TAKEAWAY: remembering a name matters, but forgetting one does not make you socially incompetent."},"joke":{"end":"They laugh and repeat it. TAKEAWAY: lightness can reduce pressure, but you never needed a perfect recovery in the first place."},"continue":{"end":"You spend the rest of the conversation managing the secret. TAKEAWAY: small honesty can be less exhausting than performance."}}},{"id":"asking-for-raise","title":"The Pay Conversation","emoji":"💼","category":"work","intro":"You have taken on more responsibility and want to ask your manager about compensation.","start":"start","nodes":{"start":{"text":"You have a meeting with your manager. Your heart is racing because the topic feels uncomfortable.","choices":[["Start with an apology.","apology"],["State the purpose clearly.","clear"],["Wait for them to bring it up.","wait"]]},"apology":{"end":"You spend so much time softening the request that the actual request becomes unclear. TAKEAWAY: you can be respectful without apologising for having a professional conversation."},"wait":{"end":"The meeting ends without the topic coming up. TAKEAWAY: important conversations often need an intentional opening."},"clear":{"text":"You say, “I’d like to discuss my responsibilities and compensation based on the work I’ve taken on.”","choices":[["Bring specific examples.","evidence"],["Ask what criteria would support a future review.","criteria"]]},"evidence":{"end":"You discuss responsibilities, examples and next steps. TAKEAWAY: a clear request becomes easier to respond to when it is grounded in specifics."},"criteria":{"end":"You leave with clearer expectations for the next review. TAKEAWAY: even when an immediate answer is unavailable, clarity can still be a useful outcome."}}},{"id":"party-introduction","title":"Walk Into the Party","emoji":"🎉","category":"social","intro":"You arrive alone at a party where you know almost nobody.","start":"start","nodes":{"start":{"text":"Music is playing. Groups are already talking. You consider turning around.","choices":[["Find the host.","host"],["Approach a small group.","group"],["Stand near the snacks and observe.","snacks"]]},"host":{"text":"The host is busy greeting people but smiles when you introduce yourself.","choices":[["Ask them to introduce you to one person.","intro"],["Thank them and explore yourself.","explore"]]},"group":{"text":"There is a pause in the conversation when you approach.","choices":[["Ask what they were talking about.","question"],["Introduce yourself simply.","intro"]]},"snacks":{"text":"You have now learned a lot about the snack table and very little about the people.","choices":[["Say hello to someone nearby.","intro"],["Stay there all night.","stay"]]},"intro":{"end":"The conversation lasts a few minutes. TAKEAWAY: social confidence can be built from tiny entries into conversations, not dramatic performances."},"explore":{"end":"You wander around and eventually find someone with a shared interest. TAKEAWAY: you do not need to be instantly comfortable to participate."},"question":{"end":"They answer and include you in the conversation. TAKEAWAY: curiosity is one of the easiest bridges into a group."},"stay":{"end":"You leave having stayed safe but unconnected. TAKEAWAY: observation can be useful; eventually, confidence needs a small action."}}},{"id":"camera-comment","title":"The Mean Comment","emoji":"📱","category":"rejection","intro":"You post something you are proud of and someone leaves a rude comment.","start":"start","nodes":{"start":{"text":"You open the comments and see: “This is embarrassing.” Your mood drops instantly.","choices":[["Delete the post.","delete"],["Reply angrily.","reply"],["Pause before deciding.","pause"]]},"delete":{"end":"You remove something you liked because one stranger disliked it. TAKEAWAY: protecting yourself is valid, but one comment does not automatically deserve control over your choices."},"reply":{"end":"The exchange becomes longer and more stressful. TAKEAWAY: not every opinion deserves your attention or a response."},"pause":{"text":"You step away for ten minutes. The post still exists.","choices":[["Check whether the comment contains useful feedback.","useful"],["Decide it is simply rude and move on.","move"]]},"useful":{"end":"There is no useful information in the comment. TAKEAWAY: you can evaluate feedback without accepting the insult attached to it."},"move":{"end":"You return to your day. TAKEAWAY: confidence online can include deciding what not to give your energy to."}}},{"id":"say-no-favour","title":"The Last-Minute Favour","emoji":"⏰","category":"boundaries","intro":"Someone asks you to do a time-consuming favour tonight, but you already have plans.","start":"start","nodes":{"start":{"text":"“Please, I really need you.” You feel guilty before you even answer.","choices":[["Say yes immediately.","yes"],["Say no briefly.","no"],["Offer a smaller alternative.","alt"]]},"yes":{"end":"You cancel your plans and spend the evening resentful. TAKEAWAY: kindness that repeatedly overrides your limits can become resentment."},"no":{"end":"You say, “I can’t tonight, but I hope you find someone who can.” TAKEAWAY: a clear no does not need a courtroom defence."},"alt":{"end":"You offer 15 minutes of help tomorrow instead of the whole evening. TAKEAWAY: boundaries can include a genuine alternative when you actually want to offer one."}}},{"id":"interview-gap","title":"The Interview Question You Can’t Answer","emoji":"🎤","category":"speaking","intro":"An interviewer asks about something you do not know.","start":"start","nodes":{"start":{"text":"Your brain goes blank. The interviewer waits.","choices":[["Pretend you know.","bluff"],["Admit you do not know and reason aloud.","honest"],["Ask to come back to it later.","later"]]},"bluff":{"end":"You give a vague answer and become more nervous. TAKEAWAY: pretending certainty can create more pressure than acknowledging a gap."},"honest":{"end":"You explain what you do know and how you would find the answer. TAKEAWAY: confidence can look like intellectual honesty plus a plan to learn."},"later":{"end":"You answer another question first and return with a clearer thought. TAKEAWAY: a pause can be a strategy, not a failure."}}},{"id":"friend-disagreement","title":"Your Friend Disagrees With You","emoji":"💬","category":"assertiveness","intro":"A close friend strongly disagrees with an opinion you care about.","start":"start","nodes":{"start":{"text":"They say, “I completely disagree with you.” You feel the urge to prove your point.","choices":[["Ask why they see it differently.","curious"],["Try to win the argument.","win"],["Say you can disagree and stay friends.","boundary"]]},"curious":{"end":"You learn something about their perspective without abandoning your own. TAKEAWAY: confidence can make room for another perspective without requiring surrender."},"win":{"end":"The conversation becomes about winning. TAKEAWAY: being right and being understood are not always the same goal."},"boundary":{"end":"You both recognise the disagreement and move on. TAKEAWAY: relationships do not require identical opinions."}}},{"id":"new-club","title":"First Day in a New Club","emoji":"🎨","category":"social","intro":"You join a club where everyone seems more experienced than you.","start":"start","nodes":{"start":{"text":"People are discussing something you barely understand. You wonder whether you belong here.","choices":[["Ask a beginner question.","question"],["Observe quietly.","observe"],["Leave before anyone notices you are new.","leave"]]},"question":{"end":"Someone explains it and invites you into the activity. TAKEAWAY: being new is not a flaw; it is a temporary stage of learning."},"observe":{"end":"You learn the basics and decide to return. TAKEAWAY: confidence does not require immediate participation every second."},"leave":{"end":"You escape the discomfort, but the club remains unfamiliar. TAKEAWAY: sometimes the bravest step is simply staying long enough to become less new."}}},{"id":"wrong-name-email","title":"The Email With the Wrong Name","emoji":"✉️","category":"work","intro":"You notice that an important email you sent contains a typo in the recipient’s name.","start":"start","nodes":{"start":{"text":"You spot the mistake immediately after pressing send.","choices":[["Send a frantic apology.","panic"],["Leave it and continue.","continue"],["Send one clean correction if needed.","correct"]]},"panic":{"end":"You send three follow-ups and create more noise than the typo needed. TAKEAWAY: urgency in your head does not always mean urgency in the situation."},"continue":{"end":"The recipient understands the message. TAKEAWAY: not every imperfection requires repair."},"correct":{"end":"You send one brief correction and move on. TAKEAWAY: confident repair is usually short, specific and finished."}}},{"id":"asking-for-help","title":"The Help You Need","emoji":"🤝","category":"self-trust","intro":"You are stuck on something and have spent an hour pretending you can solve it alone.","start":"start","nodes":{"start":{"text":"You could ask someone for ten minutes of help, but you worry they will think you are incapable.","choices":[["Keep struggling alone.","alone"],["Ask a specific question.","ask"],["Say you are completely lost.","lost"]]},"alone":{"end":"Another hour passes. TAKEAWAY: independence is valuable, but refusing reasonable help can become an unnecessary confidence test."},"ask":{"end":"They help you find the missing piece. TAKEAWAY: asking a focused question can demonstrate preparation, not weakness."},"lost":{"end":"They help, but you realise you could have explained the exact sticking point. TAKEAWAY: specificity makes asking for help easier for both people."}}},{id:'presentation-panic',title:'The Presentation Panic',emoji:'🎤',category:'speaking',intro:'Thirty seconds before your presentation, your notes suddenly look unfamiliar and your heart starts racing.',start:'start',nodes:{start:{text:'You are next. Your hands feel cold. A classmate whispers, “You got this.” You have three choices.',choices:[['Stand, exhale and read only your first sentence.','steady'],['Apologise before you even start.','apologise'],['Pretend you are not nervous and rush up.','rush']]},steady:{text:'You step forward and say your first sentence slowly. You notice the room is quieter than your fear predicted.',choices:[['Look at one friendly face and continue with your first point.','connect'],['Read every word from your phone.','phone']]},apologise:{text:'You begin with, “Sorry, I’m really nervous.” The room is still listening.',choices:[['Pause and continue instead of explaining yourself.','connect'],['Keep apologising until you feel reassured.','spiral']]},rush:{text:'You speak quickly and finish the first slide in record time. Your breathing is shallow.',choices:[['Slow down deliberately on the next sentence.','connect'],['Keep the speed because it feels safer.','spiral']]},connect:{text:'You finish your first point. Someone nods. Your voice is still a little shaky, but you are in control of your pace.',end:'You learned that confidence can coexist with nerves. TAKEAWAY: control the next sentence, not the entire room.'},phone:{text:'Your phone distracts you. You lose your place and have to improvise the next point.',end:'The presentation continues, but you notice that one simple cue card would have helped more than reading every word. TAKEAWAY: prepare support, not a script.'},spiral:{text:'You finish, but spend the rest of the day replaying every second.',end:'Nothing catastrophic happened, but the mental replay cost you more than the presentation did. TAKEAWAY: review one useful adjustment, then release the rest.'}}}
,{id:'friend-pressure',title:'The “Just Say Yes” Friend',emoji:'🫣',category:'boundaries',intro:'A friend asks you to do something you genuinely do not want to do, then jokes that you are “no fun” when you hesitate.',start:'start',nodes:{start:{text:'Your friend says, “Come on, just do it. You always overthink everything.” You feel the pressure to prove yourself.',choices:[['“I’m not comfortable with that, but I’m happy to do something else.”','clear'],['Say yes immediately so they stop asking.','yes'],['Get angry and tell them they are a terrible friend.','attack']]},clear:{text:'There is a pause. Your friend looks surprised because you usually explain yourself for five minutes.',choices:[['Let the silence exist and wait for their response.','respect'],['Start listing ten reasons you deserve to say no.','overexplain']]},yes:{text:'You agree. Ten minutes later, you regret it and feel irritated.',choices:[['Admit you changed your mind before going further.','recover'],['Keep going because you already said yes.','resent']]},attack:{text:'Your friend gets defensive. The original boundary gets buried under the argument.',choices:[['Reset: “I’m frustrated, but my answer is still no.”','respect'],['Keep arguing until they apologise.','resent']]},respect:{text:'Your friend says, “Okay.” It was less dramatic than your fear predicted.',end:'TAKEAWAY: a clear boundary can survive a little silence. You do not need to make the other person happy with your limit.'},overexplain:{text:'The longer you explain, the more openings there are for your friend to negotiate.',end:'TAKEAWAY: clarity often becomes weaker when you keep adding reasons after the boundary is already clear.'},recover:{text:'You tell them you changed your mind. They are disappointed, but you feel relieved.',end:'TAKEAWAY: changing your mind is allowed when continuing would violate your comfort or values.'},resent:{text:'You go along with it while feeling increasingly angry.',end:'TAKEAWAY: automatic yeses can turn into resentment. A pause creates room for an honest answer.'}}}
,{id:'job-interview',title:'The Unexpected Interview Question',emoji:'🧑‍💼',category:'work',intro:'Halfway through an interview, you get a question you did not prepare for.',start:'start',nodes:{start:{text:'The interviewer asks, “Tell me about a time you failed.” Your mind goes blank.',choices:[['Take a breath and ask for a moment to think.','pause'],['Invent an impressive story immediately.','invent'],['Say, “I have never really failed.”','deny']]},pause:{text:'You take two seconds. The silence feels longer to you than it probably is.',choices:[['Give a real example and focus on what changed afterward.','learn'],['Tell a vague story with no lesson.','vague']]},invent:{text:'You start a story but realise the details do not fit together.',choices:[['Pause and correct yourself honestly.','learn'],['Add more details and hope it works.','spiral']]},deny:{text:'The interviewer asks, “Nothing you would do differently?”',choices:[['Acknowledge a real mistake and what you learned.','learn'],['Keep defending the original answer.','spiral']]},learn:{text:'You describe a real mistake, what you noticed, and the specific behaviour you changed.',end:'TAKEAWAY: confidence in an interview is not perfect answers. It is the ability to think, answer honestly and show learning.'},vague:{text:'Your answer is safe but gives the interviewer little evidence.',end:'TAKEAWAY: a specific example is more useful than trying to sound flawless.'},spiral:{text:'The answer becomes longer and less clear.',end:'TAKEAWAY: pausing to think is usually safer than talking faster to escape discomfort.'}}}
,{id:'group-credit',title:'The Group Project Credit',emoji:'📚',category:'assertiveness',intro:'A group project is nearly finished, but someone presents your idea as if it were theirs.',start:'start',nodes:{start:{text:'Your teammate says, “I came up with this approach,” even though you created the framework last night.',choices:[['Add calmly: “Yes, I developed that framework; we built on it together.”','claim'],['Say nothing and hope the lecturer notices.','silent'],['Interrupt angrily: “That is literally my idea!”','angry']]},claim:{text:'The lecturer looks at you and asks you to explain the framework.',choices:[['Explain it clearly and credit the team for the parts they added.','finish'],['Use the moment to criticise your teammate.','attack']]},silent:{text:'The presentation moves on. You feel invisible and annoyed.',choices:[['Speak up later with the lecturer privately and calmly.','finish'],['Say nothing and stew over it.','regret']]},angry:{text:'The room goes quiet. Your point is valid, but the tone takes over.',choices:[['Reset and explain the contribution factually.','finish'],['Keep arguing until someone takes your side.','regret']]},finish:{text:'You state your contribution without erasing the work of the others.',end:'TAKEAWAY: giving yourself accurate credit is not arrogance. You can name your contribution while still recognising the team.'},attack:{text:'The conversation becomes about conflict rather than the work.',end:'TAKEAWAY: being right and communicating effectively are not always the same thing.'},regret:{text:'The moment passes and you wish you had said something simple.',end:'TAKEAWAY: a short factual sentence is often easier to use than waiting for the perfect confrontation.'}}}
,{id:'new-room',title:'Walking Into a Room Alone',emoji:'🚪',category:'social',intro:'You arrive at an event where you know almost nobody. Everyone seems to already have their group.',start:'start',nodes:{start:{text:'You stand near the entrance pretending to check your phone. You can leave now or create one small opening.',choices:[['Ask someone near you, “Have you been to one of these before?”','open'],['Wait until somebody notices you.','wait'],['Leave and tell yourself you were never interested.','leave']]},open:{text:'They smile and say, “Yeah, a few times.”',choices:[['Ask what they usually enjoy about it.','follow'],['Decide the answer is too short and walk away.','leave']]},wait:{text:'Five minutes pass. You feel increasingly self-conscious.',choices:[['Choose one person and use the environment as your opener.','follow'],['Stay on your phone for the whole event.','leave']]},follow:{text:'The conversation becomes easier because you have something specific to ask about.',end:'TAKEAWAY: you did not need a magical personality. You needed one small opening and a follow-up question.'},leave:{text:'You leave. Nothing terrible happened, but you never got evidence that you could handle the room.',end:'TAKEAWAY: sometimes the confidence practice is staying long enough to collect new evidence.'}}}
,{id:'wrong-message',title:'The Message You Wish You Hadn’t Sent',emoji:'📱',category:'self-trust',intro:'You send a message while emotional. Ten seconds later, you want to delete it.',start:'start',nodes:{start:{text:'You reread your message and realise the tone is sharper than you intended. The other person has not replied.',choices:[['Send a short clarification before the conversation continues.','clarify'],['Send six more messages explaining yourself.','spiral'],['Delete everything and disappear.','hide']]},clarify:{text:'You write: “That came out sharper than I intended. What I meant was…”',choices:[['State the actual issue in one or two sentences.','resolve'],['Keep apologising for having an issue.','shrink']]},spiral:{text:'Your messages get longer. You are now explaining feelings you had not even processed.',choices:[['Stop typing, put the phone down and return later.','pause'],['Send one final paragraph.','shrink']]},hide:{text:'You feel temporary relief but keep checking your phone.',choices:[['Return later and communicate clearly.','resolve'],['Keep avoiding the conversation.','shrink']]},resolve:{text:'The conversation becomes clearer once the emotion is separated from the request.',end:'TAKEAWAY: self-trust includes repairing your communication without abandoning your needs.'},pause:{text:'After ten minutes away from the phone, you can see what you actually need.',end:'TAKEAWAY: a pause can protect both your message and your relationships.'},shrink:{text:'You make yourself responsible for every emotion in the conversation.',end:'TAKEAWAY: you can own your tone without apologising for existing, asking or having a boundary.'}}}
,{id:'ask-question',title:'The Question You Are Scared to Ask',emoji:'🙋🏽‍♀️',category:'speaking',intro:'You are confused, but everyone else appears to understand.',start:'start',nodes:{start:{text:'The lecturer asks if there are questions. Your brain says, “Everyone else gets it.”',choices:[['Raise your hand and ask the exact part that confused you.','ask'],['Wait and hope the notes make sense later.','wait'],['Ask a friend privately afterward.','friend']]},ask:{text:'You ask. The lecturer says several students were wondering the same thing.',end:'TAKEAWAY: asking a useful question can help more people than just you.'},wait:{text:'You leave class still confused and now have to teach yourself the missing piece.',end:'TAKEAWAY: waiting can sometimes work, but asking early can save time and practise visibility.'},friend:{text:'Your friend explains it, but you still have a small question.',choices:[['Ask the lecturer the follow-up question anyway.','ask2'],['Decide the follow-up is too embarrassing.','wait']]},ask2:{text:'The lecturer clarifies the exact point.',end:'TAKEAWAY: confidence is often choosing clarity over the fear of looking like you do not know.'}}}
];
